/** Continuing Earth commitments use the ordinary captain quest engine. */
const catalog = new Map();
export const earthAftermathDefinitions = () => [...catalog.values()];
export const earthAftermathDefinition = id => catalog.get(id) || null;

export function buildEarthAftermaths(at) {
  const talk = (id, title, contact, text, extra = {}) => ({ id, title, kind: 'talk', at: at(contact), text, objective: `Meet ${title}.`, actionLabel: 'Continue the conversation', ...extra });
  const inspect = (id, title, object, text, objective) => ({ id, title, kind: 'inspect', at: at(object), text, objective, actionLabel: 'Check the physical record' });
  const scan = (id, title, systemId, anchorBody, text) => ({ id, title, kind: 'earth-scan', at: { systemId, anchorBody, offsetX: 640, offsetY: 280 }, text, objective: `Fly to the marked ${title.toLowerCase()} and take a close-range reading.`, actionLabel: 'Take the checked reading' });
  const option = (id, label, detail, effects = {}, cost = {}) => ({ id, label, detail, effects, cost });
  const choice = (id, title, contact, text, options) => ({ id, title, kind: 'choice', at: at(contact), text, objective: `Meet the named contact and decide: ${title.toLowerCase()}.`, options });
  const puzzle = (id, title, object, text, clues, labels, ids, solution) => ({ id, title, kind: 'puzzle', at: at(object), text, objective: `Check ${title.toLowerCase()} at the marked desk.`, actionLabel: 'Verify the procedure', puzzle: { type: 'evidence', prompt: 'Match each item to the observation or action that supports it.', clues, inputs: labels.map((label, index) => ({ id: `item-${index}`, label, options: ids.map(id => ({ id, label: id })) })), solution } });
  const base = (id, title, contact, summary, stages, extra = {}) => ({ id, title, category: 'Earth aftermath', offeredBy: contact, remoteAccept: false, summary, reward: 200,
    requires: { completed: ['earth_long_silence'] }, earthOperations: true,
    localCampaign: { focus: 'Work after the Earth investigation', scope: 'Your agreement and its named participants; other captains keep their own choices.' },
    ...extra, missionCount: stages.length, stages: stages.map((step, index) => ({ ...step, threadId: id, mission: index + 1 })) });
  const account = (flag, ...args) => base(...args, { requires: { completed: ['earth_long_silence'], flags: [`thread:earth_account_${flag}`] } });
  const commission = (id, title, contact, summary, stages, extra = {}) => base(`earth_service_${id}`, title, contact, summary, stages, { ...extra, requires: { completed: ['earth_long_silence'], flags: [`thread:earth_allegiance_${id}`] } });
  const threads = [
    account('public', 'earth_public_followup', 'After the publication', 'earth-jun', 'Your published evidence has reached people who need to check it. Help Jun produce a usable public record without exposing the remaining shelters.', [
      talk('request', 'Jun at Listening House', 'earth-jun', 'Jun has a queue of requests. “People need the actual records. They also need to know which coordinates would put a family at risk. Help me separate the two.”'),
      inspect('sources', 'The checked source index', 'earth-listening-manifest', 'Your publication is attached to the original dates. Private household routes occupy a separate appendix. This copy records your authorship; it does not overwrite another captain’s statement.', 'Check the source index at Listening House.'),
      scan('reference', 'Listening House verification beacon', 'vesper', 'listening', 'You record a fresh timing reference so readers can distinguish the original evidence from a copied or altered transmission.'),
      choice('access', 'How to keep the record usable', 'earth-jun', 'Jun can print a public checking guide or fund a staffed reply desk. Both retain the verified finding and protect private addresses.', [
        option('guide', 'Publish the checking guide', 'The records stay accessible without a staff member interpreting every request.', { flags: ['earth_public_guide'], memory: 'You published a practical method for checking your Earth findings.' }),
        option('desk', 'Fund a staffed reply desk · 45 cr', 'Readers can ask someone to help them check the material.', { flags: ['earth_public_desk'], memory: 'You funded a staffed verification desk for the people answering your publication.' }, { credits: 45 })
      ]),
      talk('handover', 'Jun at Listening House', 'earth-jun', 'The next reader checks a date without asking you what to believe. Your Listening House treatment agreement now covers 20% of the fee. The publication can still be criticized; its evidence can be checked.', { completionFlag: 'earth_public_service' })
    ]),
    account('sanitized', 'earth_cover_followup', 'Keeping the cover story', 'earth-ryn', 'Your infrastructure explanation is being challenged by people who saw biological hazards. Eren asks you to decide what you will sign next.', [
      talk('request', 'Eren at Ledger Ring', 'earth-ryn', 'Eren sets your statement beside a witness’s photograph. “The warning kept this ship out. The explanation is false. I can help you maintain the filing, but I will not sign it for you.”'),
      inspect('comparison', 'The two filed accounts', 'earth-ledger-contract', 'The witness saw living growth. Your statement attributed closure only to failed machinery. Both are now attached to your file; neither disappears when you choose the next reply.', 'Compare your statement and the witness report at Ledger Ring.'),
      scan('inspection', 'Checkpoint Sable inspection receipt', 'sable', 'checkpoint', 'The screening notice records a real hazard. You bring back the signed receipt before answering the complaint.'),
      choice('reply', 'Maintain the lie or correct it', 'earth-ryn', 'You have to put your own name on the reply.', [
        option('maintain', 'Maintain the cover story', 'Call the biological report unverified despite your own evidence. The original warning stays in force.', { rep: { lantern: -5, meridian: 2 }, flags: ['earth_cover_maintained'], memory: 'You knowingly defended your false infrastructure account against a supported witness report.' }),
        option('correct', 'Publish a signed correction', 'Name the biological cause and link the original evidence. The old false statement remains attributable to you.', { rep: { lantern: 5, concord: -2 }, flags: ['earth_cover_corrected'], memory: 'You corrected your cover story without erasing the record that you had issued it.' })
      ]),
      talk('handover', 'Eren at Ledger Ring', 'earth-ryn', 'The complaint has a signed answer. Eren’s workshop pays your verification fee and grants a 15% Ledger hull-repair rate. It is payment for checked work, not an endorsement of your account.', { completionFlag: 'earth_cover_service' })
    ]),
    account('false_return', 'earth_return_followup', 'The ships that believed you', 'silas-voss', 'The Homeward Seven convoy sold tickets using your false all-clear. Captain Ira Fen is requesting a final route check. You can correct the lie or keep supporting it.', [
      talk('request', 'Silas Voss at Kettle', 'silas-voss', 'Silas shows you the passenger count. “Homeward Seven used your name. Ira wants one more check before taking them through.” He offers a bonus if you keep the departure on schedule.'),
      scan('convoy', 'Homeward Seven holding position', 'sol', 'threshold', 'Ira’s screened transport is waiting at Threshold. The next route enters an unsafe zone. Your own survey contradicts the assurance used to sell these tickets.'),
      choice('route', 'What will you tell the convoy?', 'earth-sol', 'Suri will carry your message under your own transponder. “Tell Ira the truth. If you lie again, it goes in your name, not mine.”', [
        option('recall', 'Admit the lie and recall the convoy', 'Ira starts turning the passengers back. You accept responsibility and forfeit the broker’s bonus.', { rep: { freewake: 3, lantern: 2 }, flags: ['earth_false_return_recalled'], memory: 'You admitted the false all-clear and recalled Homeward Seven before its final approach.' }),
        option('continue', 'Repeat the false all-clear · 350 cr', 'Knowingly urge the convoy toward the unsafe route. The broker pays for your continued assurance.', { credits: 350, rep: { freewake: -6, concord: -6, lantern: -8 }, flags: ['earth_false_return_reaffirmed'], memory: 'You repeated the false all-clear and accepted payment while Homeward Seven entered known danger.' })
      ]),
      { id: 'relay-watch', title: 'Homeward Seven traffic relay', kind: 'earth-defense', at: { systemId: 'sol', anchorBody: 'threshold', offsetX: 900, offsetY: 280 }, text: 'Salvage raiders are attacking the convoy’s traffic relay. Keep the relay working so the remaining ships can communicate. Protecting it does not undo the route message you sent.', objective: 'Protect the marked convoy relay for 30 seconds and neutralize both raider waves.', duration: 30, deadline: 150, integrity: 120, waves: [{ at: 0, count: 1, hp: 80 }, { at: 15, count: 1, hp: 90 }], enemyName: 'Convoy raider', enemyFaction: 'raider', actionLabel: 'Confirm the relay is secure' },
      { id: 'ira-pickup', title: 'Ira Fen’s capsule', kind: 'earth-rescue', at: { systemId: 'sol', anchorBody: 'threshold', offsetX: 740, offsetY: -330 }, text: 'Ira ejected after the relay attack disabled the lead transport. Her capsule has one living occupant. Bring the actual person aboard; a report cannot substitute for a rescue.', objective: 'Recover Ira’s capsule with one free physical berth.', passenger: { id: 'convoy-ira', name: 'Ira Fen', role: 'Homeward Seven captain' }, actionLabel: 'Recover Ira Fen · 1 berth' },
      { id: 'ira-delivery', title: 'A witness at the receiving bay', kind: 'earth-deliver', at: at('earth-sol'), rescueId: 'ira-pickup', text: 'Ira reaches Threshold’s receiving bay and signs her own account. She can testify about the assurance you sent and the ships that followed it. Your choice remains recorded; bringing her ashore does not erase it.', objective: 'Dock the carrying ship at Threshold and bring Ira to Suri.', actionLabel: 'Disembark Ira at Threshold' },
      talk('account', 'Suri at Threshold', 'earth-sol', 'Suri files Ira’s account separately from yours.', { respondTo: 'route', responses: {
        recall: 'The recalled passenger transports reach screened holding berths. Ira names the lie and the later recall in the same statement. The passengers are alive; some will never trust you again.',
        continue: 'Two transports followed your second assurance beyond the screened route. Their last cameras show occupied cabins overtaken by growth. One transport turned back. Ira has its survivors and the record of your warning. This loss belongs to your convoy, not to every ship or captain in the galaxy.'
      }, completionFlag: 'earth_return_accounted' })
    ]),
    account('custody', 'earth_custody_followup', 'Copies beyond one office', 'earth-ot', 'Your independent record needs real custodians. Carry the checked copies to two people who can challenge each other without asking a faction’s permission.', [
      talk('request', 'Ot at Blindpost', 'earth-ot', 'Ot has prepared two sealed copies and an index of what each contains. “A locked box is not independent custody if I am the only person with a key.”'),
      inspect('index', 'The custody index', 'earth-hush-order', 'The index lists the evidence, its original source and the people permitted to see private routes. The public danger warning is attached outside the seal.', 'Check the custody index at Blindpost.'),
      talk('first-copy', 'Jun at Listening House', 'earth-jun', 'Jun checks the first copy against the source index and signs for it. She promises to record disagreements instead of silently replacing an inconvenient page.'),
      talk('second-copy', 'Nima at Bastion Three', 'earth-sef', 'Nima keeps a second copy outside the archive administration. “Anyone using this to move patients must show us their actual route.”'),
      talk('handover', 'Ot at Blindpost', 'earth-ot', 'Both custodians have signed. Your Blindpost workshop agreement covers 20% of hull repairs. The verified originals remain available to challenge your account.', { completionFlag: 'earth_custody_service' })
    ]),
    commission('concord', 'The screened departure watch', 'earth-sol', 'Help Suri turn an emergency inspection into a procedure crews can actually follow.', [
      talk('request', 'Suri at Threshold', 'earth-sol', 'A restoration officer wants every outbound hull held indefinitely. Suri wants the ships checked and their people allowed to leave when the checks pass.'),
      scan('departure', 'Luna departure sample point', 'sol', 'luna', 'The sealed sampling boom checks an outbound route without bringing live material into the ship.'),
      puzzle('procedure', 'The departure procedure', 'earth-recall-console', 'Suri’s procedure separates a failed screen from an automatic permanent detention.', ['First isolate the suspect cargo.', 'Then verify the treatment with a fresh sample.', 'Authorize departure only after that sample passes.'], ['First', 'Second', 'Third'], ['isolate', 'verify', 'release'], ['isolate', 'verify', 'release']),
      talk('handover', 'Suri at Threshold', 'earth-sol', 'The first cleared ship departs. Your earned Threshold agreement covers 25% of repairs and treatment. You can keep doing relief work without endorsing every Continuity order.', { completionFlag: 'earth_service_concord' })
    ]),
    commission('freewake', 'Supplies for the people arriving', 'earth-tess', 'Tess needs a practical receiving plan for people leaving Sol, not another speech about solidarity.', [
      talk('request', 'Tess at the Weighhouse', 'earth-tess', '“We have meals for tonight,” Tess says. “What I need is a shipment schedule and a working spare before everyone arrives.”'),
      inspect('manifest', 'The receiving stores', 'earth-brindle-manifest', 'The stores have food and medicine but no spare regulator. The missing part is marked openly; nobody has billed it as already delivered.', 'Check the receiving stores at the Weighhouse.'),
      choice('support', 'Supply the receiving bay', 'earth-tess', 'Tess will accept parts from your docked ship or buy them locally with your payment.', [option('parts', 'Supply 4 ore from your docked ship', 'The workshop makes the missing regulator.', { memory: 'You supplied the Weighhouse receiving bay’s regulator material.' }, { ore: 4 }), option('pay', 'Buy the regulator · 60 cr', 'Tess buys the missing part without taking from another shelter’s stores.', { memory: 'You funded the Weighhouse receiving bay’s regulator.' }, { credits: 60 })]),
      talk('handover', 'Tess at the Weighhouse', 'earth-tess', 'The receiving bay passes its load test. Your Weighhouse agreement now covers 30% of treatment costs. The new arrivals are meeting the people who already live here.', { completionFlag: 'earth_service_freewake' })
    ]),
    commission('meridian', 'A contract that names its cargo', 'earth-ryn', 'Eren needs an actual cargo check before approving a continuing supply contract.', [
      talk('request', 'Eren at Ledger Ring', 'earth-ryn', '“Do not promise me a clean shipment,” Eren says. “Bring the reading. I will put my own signature beside it.”'),
      scan('cargo', 'Checkpoint Sable cargo reference', 'sable', 'checkpoint', 'The reading separates the licensed shipment from an unlisted return consignment. The equipment and route match the contract.'),
      puzzle('invoice', 'The audited invoice', 'earth-ledger-contract', 'Fees, consent and inspections need different signatures.', ['The carrier signs for transport.', 'The receiving clinic signs for acceptance.', 'The inspector signs the actual screen.'], ['Transport', 'Acceptance', 'Screen'], ['carrier', 'clinic', 'inspector'], ['carrier', 'clinic', 'inspector']),
      talk('handover', 'Eren at Ledger Ring', 'earth-ryn', 'The contract pays for work that was actually checked. Ledger hull repairs now cost you 25% less under this agreement. Brokers outside Eren’s service remain responsible for their own claims.', { completionFlag: 'earth_service_meridian' })
    ]),
    commission('lantern', 'Another observer can check it', 'earth-jun', 'Jun wants the next crew to reproduce a reading without depending on your authority.', [
      talk('request', 'Jun at Listening House', 'earth-jun', '“You know what happened,” Jun says. “The next captain needs a way to find out whether a new report is true.”'),
      scan('reference', 'Witness independent timing point', 'witness', 'census', 'You collect a fresh reference from the actual ship’s scanner. It is a measurement, not a copy of your conclusion.'),
      puzzle('method', 'The independent checking method', 'earth-listening-manifest', 'The new guide must say what was measured, where the source is and what remains uncertain.', ['The raw reading is the measurement.', 'The signed receiver log identifies its source.', 'The limits note lists the questions this reading cannot answer.'], ['Measurement', 'Source', 'Limits'], ['reading', 'receiver', 'limits'], ['reading', 'receiver', 'limits']),
      talk('handover', 'Jun at Listening House', 'earth-jun', 'A second observer reproduces the check. Your calibrated ordinary scanner now uses 4 charge. Story readings retain their own requirements; good calibration does not manufacture evidence.', { completionFlag: 'earth_service_lantern' })
    ]),
    commission('cinder', 'A refuge with working filters', 'earth-ot', 'Ot has a practical request from the Patchwork crews: inspect the refuge approach and replace a failed filter.', [
      talk('request', 'Ot at Blindpost', 'earth-ot', '“The old warning was useful,” Ot says. “Repeating it is not maintenance. Someone still has to check the refuge.”'),
      scan('refuge', 'Patchwork refuge approach', 'cinder', 'patchwork', 'The approach is clear. The refuge’s filter warning is genuine and local; it is not a sign that every Cinder ship is infected.'),
      choice('filter', 'Replace the failed filter', 'ferryman', 'The Ferryman can fit a spare made from your material or buy one at the anchorage.', [option('parts', 'Supply 3 ore from your docked ship', 'The spare goes into the named refuge lock.', { memory: 'You supplied a working filter for the Patchwork refuge.' }, { ore: 3 }), option('buy', 'Buy the filter · 45 cr', 'The refuge crew gets the replacement without another debt.', { memory: 'You bought the Patchwork refuge’s replacement filter.' }, { credits: 45 })]),
      talk('handover', 'The Ferryman at Patchwork', 'ferryman', 'The filter passes its check. Your Patchwork hull-repair agreement covers 25% of the cost. The refuge keeps its own guest list; the compact does not make its occupants your property.', { completionFlag: 'earth_service_cinder' })
    ]),
    commission('rogue', 'A berth without a commission', 'earth-vale', 'Oren can offer a working arrangement without asking you to represent a faction.', [
      talk('request', 'Oren at Kettle', 'earth-vale', '“Independent is fine,” Oren says. “The invoices still need paying. Check this approach and we will keep a repair slot for you.”'),
      scan('approach', 'Kettle relief approach', 'hearth', 'kettle', 'You verify the public approach used by working relief ships. The measurement does not depend on an Earth allegiance.'),
      inspect('list', 'The ordinary receiving list', 'clinic-case', 'Morrow’s next receiving list contains patients, shift workers and spare filters. Their journeys do not wait for agreement about Earth.', 'Check the receiving list beside Morrow’s medicine case.'),
      talk('handover', 'Oren at Kettle', 'earth-vale', 'The berth is entered under your captain’s name. Kettle repairs cost you 20% less. You still decide which jobs to take and which people to answer.', { completionFlag: 'earth_service_rogue' })
    ]),
    commission('reservoir', 'The terms of contact', 'earth-hale', 'Hale will set up a contained working channel. Joining begins with an explicit procedure, not surrendering your character or your ship.', [
      talk('request', 'Hale at Earth’s boundary desk', 'earth-hale', 'Hale reads the terms aloud. “You keep the helm and your own judgment. The contact gets only the records you choose to send. No living material crosses this desk.”'),
      inspect('boundary', 'The isolated connection', 'earth-isolated-link', 'The contact equipment has a physical network break and a separate drain. A sealed sample chamber cannot open into the shelter.', 'Inspect the isolated boundary channel on Earth.'),
      scan('baseline', 'Earth boundary reference', 'sol', 'earth', 'The external sensor records the edge of the connected growth. Your ship remains outside it. A limited observation does not grant the contact control of your instruments.'),
      puzzle('seal', 'The contained contact procedure', 'earth-isolated-link', 'Test the boundary before accepting service materials.', ['First close the material shutter.', 'Then run the independent heat test.', 'Open the data channel only after the shutter and test pass.'], ['First', 'Second', 'Third'], ['shutter', 'test', 'data'], ['shutter', 'test', 'data']),
      talk('handover', 'Hale at Earth’s boundary desk', 'earth-hale', 'The isolated service accepts your terms. Screened treatment and hull work on Earth cost you 40% less while you cooperate. Hale now offers paid field observations. You remain free to travel, refuse a request or end the agreement.', { completionFlag: 'earth_service_reservoir' })
    ]),
    base('earth_reservoir_watch', 'Field work for the contact', 'earth-hale', 'Carry out a fresh physical observation for the Earth contact, then decide whether to share it. The contact cannot see or direct your voyage.', [
      talk('request', 'Hale at Earth’s boundary desk', 'earth-hale', 'The contact wants a reading at an Eridani industrial outlet. Hale supplies an isolated recorder. “It receives what you submit. It cannot listen through your ship.”'),
      scan('field', 'Eridani sealed outlet', 'epsilon-eridani', 'epsilon-eridani-yard', 'You record the outlet’s temperature and material throughput from the marked point. This is a new field reading, not a payment for repeating old testimony.'),
      choice('submission', 'Share the reading or leave the agreement', 'earth-hale', 'The contact says the reading will help it understand machinery beyond Sol. You decide what to hand over.', [
        option('share', 'Submit this reading · 260 cr', 'Give the contact the measured industrial record. Hale settles the field fee; another watch becomes available later.', { credits: 260, flags: ['earth_contact_work_done'], memory: 'You supplied a fresh industrial observation to the Reservoir under the contained contact agreement.' }),
        option('refuse', 'Withhold it and end the agreement', 'Keep the reading. Your discounted contact services end and you continue as an independent captain.', { flags: ['earth_reservoir_left'], memory: 'You withheld the field reading and ended your agreement with the Reservoir.' })
      ])
    ], { reward: 0, repeatable: true, repeatDelay: 180, requires: { completed: ['earth_service_reservoir'], notFlags: ['thread:earth_reservoir_left'] } })
  ];
  for (const definition of threads) catalog.set(definition.id, definition);
  return threads;
}
